import torch


def run_correctness(x, y):
    output = torch.ops.aten.special_xlog1py(x.float(), y.float())
    return output.to(x.dtype)


def run(x, y):
    return torch.ops.aten.special_xlog1py(x, y)


def gen_inputs(ctx, device):
    import torch

    def _to_dtype(s):
        s = str(s).replace("torch.", "")
        return getattr(torch, s)

    shape = list(ctx["x__shape"])
    dtype = _to_dtype(ctx["x__dtype"])
    if shape == [10]:
        # test_special_xlog1py_x_zero: x == 0, y = linspace(-0.5, 2.0, 10)
        x = torch.zeros(shape, dtype=dtype, device=device)
        y = torch.linspace(-0.5, 2.0, 10, dtype=dtype, device=device)
    elif shape == [13]:
        # test_special_xlog1py_y_nan: y is NaN => result is NaN
        x = torch.randn(shape, dtype=dtype, device=device)
        y = torch.full(shape, float("nan"), dtype=dtype, device=device)
    else:
        # test_special_xlog1py: randn inputs, second operand clamped into domain
        x = torch.randn(shape, dtype=dtype, device=device)
        y = torch.randn(shape, dtype=dtype, device=device).clamp(min=-1.0 + 1e-6)
    return {"x": x, "y": y}


def valid(ref_outputs, sol_outputs, inputs, ctx):
    import torch

    ref = ref_outputs[0].detach().to("cpu").to(torch.float64)
    sol = sol_outputs[0].detach().to("cpu").to(torch.float64)
    if ref.shape != sol.shape:
        return {"passed": False, "message": f"shape {sol.shape} vs {ref.shape}", "metrics": {}}
    dtype = str(ctx.get("x__dtype", "float32")).replace("torch.", "")
    rtol_map = {"float16": 1e-3, "bfloat16": 1.6e-2, "float32": 1.3e-6, "float64": 1e-7}
    rtol = rtol_map.get(dtype, 1e-3)
    atol = 1e-4
    both_nan = torch.isnan(ref) & torch.isnan(sol)
    both_posinf = torch.isposinf(ref) & torch.isposinf(sol)
    both_neginf = torch.isneginf(ref) & torch.isneginf(sol)
    finite = torch.isfinite(ref) & torch.isfinite(sol)
    close = torch.zeros_like(ref, dtype=torch.bool)
    close[finite] = (ref[finite] - sol[finite]).abs() <= atol + rtol * ref[finite].abs()
    ok = (close | both_nan | both_posinf | both_neginf).all().item()
    return {"passed": bool(ok), "message": "", "metrics": {}}
